export class PostProcessGraph {
    disposed = false;
    passes = [];
    add(...passes) { this.assertAlive(); this.passes.push(...passes); return this; }
    remove(pass) { const index = this.passes.indexOf(pass); if (index < 0)
        return false; this.passes.splice(index, 1); return true; }
    async process(frame, width, height, deltaTime = 0) {
        this.assertAlive();
        let output = frame;
        for (const pass of this.passes)
            if (pass.enabled)
                output = await pass.process({ frame: output, width, height, deltaTime });
        return output;
    }
    dispose() { if (this.disposed)
        return; this.disposed = true; for (const pass of this.passes)
        pass.dispose?.(); this.passes.length = 0; }
    assertAlive() { if (this.disposed)
        throw new Error('PostProcessGraph is disposed.'); }
}